create table slt_private.release_state(id integer primary key check(id=1), active boolean not null default false, source_checksum text, source_revision bigint, activated_at timestamptz);
insert into slt_private.release_state(id) values(1);
create table slt_private.import_stage(entity text not null references slt_private.entity_catalog, record_key text not null, record jsonb not null, primary key(entity,record_key));
create table slt_private.migration_runs(id bigint generated always as identity primary key, source_checksum text not null, source_revision bigint not null, records integer not null, counts jsonb not null, completed_at timestamptz not null default now());
create table slt_private.write_receipts(actor uuid not null, request_id uuid not null, input_hash text not null, result jsonb not null, created_at timestamptz not null default now(),primary key(actor,request_id));
alter table public.slt360_profiles drop constraint slt360_profiles_perfil_check;
alter table public.slt360_profiles add constraint slt360_profiles_perfil_check check(perfil in ('Admin','Gestor','Analista'));

create table public.slt_core_module_access(user_id uuid not null references public.slt360_profiles(id) on delete cascade, module text not null check(module in ('core','projects','budget','maintenance','clinical','finance')), can_read boolean not null default true, can_write boolean not null default false, primary key(user_id,module), check(not can_write or can_read));
alter table public.slt_core_module_access enable row level security;
revoke all on public.slt_core_module_access from public,anon,authenticated;
grant select on public.slt_core_module_access to authenticated;
create policy own_module_access on public.slt_core_module_access for select to authenticated using(user_id=(select auth.uid()) or (select public.slt360_is_admin()));
create function public.slt_has_module_access(module_key text, writing boolean default false) returns boolean language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.slt360_profiles p where p.id=(select auth.uid()) and p.ativo and not p.must_change_password and
    (p.perfil='Admin' or exists(select 1 from public.slt_core_module_access g where g.user_id=p.id and g.module=module_key and g.can_read and (not writing or g.can_write))));
$$;
revoke all on function public.slt_has_module_access(text,boolean) from public,anon;
grant execute on function public.slt_has_module_access(text,boolean) to authenticated;

create table public.slt_core_change_log(id bigint generated always as identity primary key,module text not null,entity text not null,record_key text not null,operation text not null check(operation in ('insert','update','delete')),actor uuid references auth.users(id),request_id uuid not null,before_values jsonb,after_values jsonb,created_at timestamptz not null default now());
create index slt_change_log_entity on public.slt_core_change_log(entity,record_key,created_at desc);
create index slt_change_log_actor on public.slt_core_change_log(actor,created_at desc);
alter table public.slt_core_change_log enable row level security;
revoke all on public.slt_core_change_log from public,anon,authenticated;
grant select on public.slt_core_change_log to authenticated;
create policy scoped_change_log on public.slt_core_change_log for select to authenticated using(public.slt_has_module_access(module,false));

-- Each business entity is a physical relational table with typed fields and its own RLS.
do $$ declare e record; fld record; statement text; begin
 for e in select * from slt_private.entity_catalog order by name loop
  statement=format('create table public.%I (record_key text primary key check(length(record_key) between 1 and 1500), revision bigint not null default 1 check(revision>0), ordinal numeric not null default 0, parent_key text, child_fields text[] not null default array[]::text[], field_keys text[] not null default array[]::text[], empty_fields text[] not null default array[]::text[], string_fields text[] not null default array[]::text[], extra jsonb not null default ''{}''::jsonb check(jsonb_typeof(extra)=''object''), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid references auth.users(id), deleted_at timestamptz', 'slt_'||e.name);
  for fld in select key,value from jsonb_each(e.definition->'fields') loop
    statement=statement||format(', %I %s',fld.value->>'name',fld.value->>'type');
  end loop;
  execute statement||')';
  execute format('alter table public.%I enable row level security','slt_'||e.name);
  execute format('revoke all on public.%I from public,anon,authenticated','slt_'||e.name);
  execute format('grant select on public.%I to authenticated','slt_'||e.name);
  execute format('create policy module_read on public.%I for select to authenticated using(deleted_at is null and (select public.slt_has_module_access(%L,false)))','slt_'||e.name,e.module);
  execute format('create index on public.%I(updated_at) where deleted_at is null','slt_'||e.name);
 end loop;
 for e in select * from slt_private.entity_catalog order by name loop
  if e.definition ? 'parent' then
    execute format('alter table public.%I add foreign key(parent_key) references public.%I(record_key) deferrable initially deferred','slt_'||e.name,'slt_'||(e.definition->>'parent'));
    execute format('alter table public.%I add check(parent_key is not null)','slt_'||e.name);
    execute format('create index on public.%I(parent_key)','slt_'||e.name);
  end if;
  for fld in select key,value from jsonb_each(e.definition->'fields') loop
    if fld.value ? 'reference' then
      execute format('alter table public.%I add foreign key(%I) references public.%I(record_key) deferrable initially deferred','slt_'||e.name,fld.value->>'name','slt_'||(fld.value->>'reference'));
    end if;
    if fld.value ? 'reference' or fld.value->>'name' in ('status','phase','internal_order','unit_code','work_code','service_order','due_date') then
      execute format('create index on public.%I(%I) where deleted_at is null','slt_'||e.name,fld.value->>'name');
    end if;
  end loop;
 end loop;
end $$;

create function slt_private.decode_record(entity_name text, row_value jsonb) returns jsonb language plpgsql stable set search_path='' as $$
declare result jsonb=row_value->'extra'; fld record; v jsonb; begin
 for fld in select key,value from jsonb_each((select definition->'fields' from slt_private.entity_catalog where name=entity_name)) loop
  if (row_value->'field_keys') ? fld.key then
   v=case when (row_value->'empty_fields') ? fld.key and row_value->(fld.value->>'name')='null'::jsonb then '""'::jsonb else coalesce(row_value->(fld.value->>'name'),'null'::jsonb) end;
   if (row_value->'string_fields') ? fld.key and v<>'null'::jsonb and v<>'""'::jsonb then v=to_jsonb(row_value->>(fld.value->>'name')); end if;
   result=result||jsonb_build_object(fld.key,v);
  end if;
 end loop;
 return jsonb_build_object('entity',entity_name,'key',row_value->'record_key','revision',row_value->'revision','ordinal',row_value->'ordinal','parent_key',row_value->'parent_key','child_fields',row_value->'child_fields','document',result);
end $$;

-- Internal encoder cannot be called through PostgREST or by authenticated users.
create function slt_private.put_record(change jsonb, actor_id uuid, importing boolean default false) returns bigint language plpgsql set search_path='' as $$
declare cfg jsonb; item jsonb=change->'document'; key text=change->>'key'; tab text; before_row jsonb; values_json jsonb; fld record; value jsonb; columns_sql text; values_sql text; updates_sql text; expected bigint; next_revision bigint; empty_keys text[]='{}'; present_keys text[]='{}'; string_keys text[]='{}'; allowed_children text[]; child text; other record; has_dependents boolean;
begin
 select definition into cfg from slt_private.entity_catalog where name=change->>'entity';
 if cfg is null then raise exception 'Entidade desconhecida' using errcode='22023'; end if;
 tab='slt_'||(cfg->>'name');
 if not importing and (coalesce((cfg->>'readonly')::boolean,false) or not public.slt_has_module_access(cfg->>'module',true)) then raise exception 'Sem permissão de gravação neste módulo' using errcode='42501'; end if;
 if length(key) not between 1 and 1500 then raise exception 'Identificador inválido' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(tab||'/'||key,0));
 execute format('select to_jsonb(t) from public.%I t where record_key=$1 for update',tab) into before_row using key;
 expected=coalesce((change->>'expected_revision')::bigint,0);
 if not importing and (coalesce((before_row->>'revision')::bigint,0)<>expected or before_row->>'deleted_at' is not null) then raise exception 'Registro alterado em outra sessão: %',tab using errcode='40001'; end if;
 next_revision=coalesce((before_row->>'revision')::bigint,0)+1;
 if change->>'operation'='delete' then
  if before_row is null then raise exception 'Registro inexistente' using errcode='22023'; end if;
  for other in select name,definition from slt_private.entity_catalog where definition->>'parent'=cfg->>'name' loop
   execute format('select exists(select 1 from public.%I where parent_key=$1 and deleted_at is null)','slt_'||other.name) into has_dependents using key;
   if has_dependents then raise exception 'Exclua os registros dependentes primeiro' using errcode='23503'; end if;
  end loop;
  execute format('update public.%I set deleted_at=now(),updated_at=now(),updated_by=$2,revision=$3 where record_key=$1',tab) using key,actor_id,next_revision;
  return next_revision;
 end if;
 if jsonb_typeof(item) is distinct from 'object' or item ?| array['password','senha','users','activeRole'] then raise exception 'Registro inválido' using errcode='22023'; end if;
 select coalesce(array_agg(definition->>'child'),'{}') into allowed_children from slt_private.entity_catalog where definition->>'parent'=cfg->>'name';
 if item ?| allowed_children then raise exception 'Filhos devem usar as próprias tabelas' using errcode='22023'; end if;
 if not array(select jsonb_array_elements_text(coalesce(change->'child_fields','[]'))) <@ allowed_children then raise exception 'Relação inválida' using errcode='22023'; end if;
 values_json=jsonb_build_object('record_key',key,'ordinal',coalesce(change->'ordinal','0'),'parent_key',change->'parent_key','child_fields',coalesce(change->'child_fields','[]'),'revision',next_revision,'updated_at',now(),'updated_by',actor_id,'deleted_at',null);
 for fld in select j.key,j.value from jsonb_each(cfg->'fields') j loop
  value=coalesce(item->fld.key,'null'::jsonb);
  if item ? fld.key then present_keys=array_append(present_keys,fld.key); end if;
  if jsonb_typeof(value)='string' and fld.value->>'type' in ('numeric','integer') then string_keys=array_append(string_keys,fld.key); end if;
  if value='""'::jsonb and (fld.value->>'type'<>'text' or fld.value ? 'reference') then empty_keys=array_append(empty_keys,fld.key); value='null'::jsonb; end if;
  values_json=values_json||jsonb_build_object(fld.value->>'name',value);
 end loop;
 values_json=values_json||jsonb_build_object('field_keys',present_keys,'empty_fields',empty_keys,'string_fields',string_keys,'extra',item-array(select jsonb_object_keys(cfg->'fields')));
 select string_agg(format('%I',k),','), string_agg(format('v.%I',k),','), string_agg(format('%I=excluded.%I',k,k),',') into columns_sql,values_sql,updates_sql from jsonb_object_keys(values_json) k;
 execute format('insert into public.%I(%s) select %s from jsonb_populate_record(null::public.%I,$1) v on conflict(record_key) do update set %s',tab,columns_sql,values_sql,tab,updates_sql) using values_json;
 return next_revision;
end $$;

create function public.slt_module_load(module_key text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare e record; result jsonb='[]'; rows_json jsonb; begin
 if not (select active from slt_private.release_state where id=1) then raise exception 'Migração modular ainda não ativada' using errcode='55000'; end if;
 if not exists(select 1 from public.slt360_profiles where id=(select auth.uid()) and ativo and not must_change_password) then raise exception 'Acesso negado' using errcode='42501'; end if;
 if module_key is not null and not public.slt_has_module_access(module_key,false) then raise exception 'Acesso negado ao módulo' using errcode='42501'; end if;
 for e in select name,module from slt_private.entity_catalog where (module_key is null or module=module_key) order by name loop
  if public.slt_has_module_access(e.module,false) then
   execute format('select coalesce(jsonb_agg(slt_private.decode_record(%L,to_jsonb(t)) order by ordinal,record_key),''[]'') from public.%I t where deleted_at is null',e.name,'slt_'||e.name) into rows_json;
   result=result||rows_json;
  end if;
 end loop;
 return jsonb_build_object('schema_version',2,'records',result);
end $$;
revoke all on function public.slt_module_load(text) from public,anon;
grant execute on function public.slt_module_load(text) to authenticated;

create function public.slt_commit_changes(request_id uuid, changes jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor_id uuid=auth.uid(); input_hash text; receipt slt_private.write_receipts; change jsonb; cfg jsonb; previous jsonb; current_row jsonb; new_revision bigint; results jsonb='[]'; operation text; batch_keys integer;
begin
 if not (select active from slt_private.release_state where id=1) then raise exception 'Atualize o sistema para continuar' using errcode='55000'; end if;
 if actor_id is null or not exists(select 1 from public.slt360_profiles where id=actor_id and ativo and not must_change_password) then raise exception 'Acesso negado' using errcode='42501'; end if;
 if request_id is null or jsonb_typeof(changes) is distinct from 'array' or jsonb_array_length(changes)>5000 or octet_length(changes::text)>12000000 then raise exception 'Lote inválido' using errcode='22023'; end if;
 input_hash=md5(changes::text);
 perform pg_advisory_xact_lock(hashtextextended(actor_id::text||request_id::text,0));
 select * into receipt from slt_private.write_receipts r where r.actor=actor_id and r.request_id=slt_commit_changes.request_id;
 if found then
  if receipt.input_hash<>input_hash then raise exception 'Chave de operação reutilizada' using errcode='22023'; end if;
  return receipt.result;
 end if;
 select count(distinct (v->>'entity',v->>'key')) into batch_keys from jsonb_array_elements(changes) v;
 if batch_keys<>jsonb_array_length(changes) then raise exception 'Registro repetido no lote' using errcode='22023'; end if;
 -- The client orders parents before children for inserts, and the reverse for deletes.
 for change in select value from jsonb_array_elements(changes) loop
  select definition into cfg from slt_private.entity_catalog where name=change->>'entity';
  if cfg is null then raise exception 'Entidade desconhecida' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('slt_'||(cfg->>'name')||'/'||(change->>'key'),0));
  execute format('select to_jsonb(t) from public.%I t where record_key=$1','slt_'||(cfg->>'name')) into previous using change->>'key';
  new_revision=slt_private.put_record(change,actor_id,false);
  execute format('select to_jsonb(t) from public.%I t where record_key=$1','slt_'||(cfg->>'name')) into current_row using change->>'key';
  operation=case when change->>'operation'='delete' then 'delete' when previous is null then 'insert' else 'update' end;
  insert into public.slt_core_change_log(module,entity,record_key,operation,actor,request_id,before_values,after_values)
   values(cfg->>'module',cfg->>'name',change->>'key',operation,actor_id,slt_commit_changes.request_id,previous,current_row);
  results=results||jsonb_build_array(jsonb_build_object('entity',cfg->>'name','key',change->>'key','revision',new_revision));
 end loop;
 insert into slt_private.write_receipts(actor,request_id,input_hash,result) values(actor_id,request_id,input_hash,results);
 return results;
end $$;
revoke all on function public.slt_commit_changes(uuid,jsonb) from public,anon;
grant execute on function public.slt_commit_changes(uuid,jsonb) to authenticated;

-- The original snapshot is retained for rollback and exact import provenance.
-- No client can read or write it after the guarded activation.
create function slt_private.activate_modules(expected_checksum text,expected_records integer) returns jsonb language plpgsql set search_path='' as $$
declare source public.slt360_state; row record; counts jsonb; inserted integer=0; actual integer; begin
 select * into source from public.slt360_state where id=1 for update;
 if (select active from slt_private.release_state where id=1) then raise exception 'Migração já ativada'; end if;
 if md5(source.payload::text) is distinct from expected_checksum then raise exception 'A base mudou: refaça a exportação antes de migrar'; end if;
 if (select count(*) from slt_private.import_stage)<>expected_records then raise exception 'Importação incompleta'; end if;
 for row in select record from slt_private.import_stage order by (record->>'depth')::integer,entity,record_key loop
  perform slt_private.put_record(row.record,null,true); inserted=inserted+1;
 end loop;
 set constraints all immediate;
 for row in select entity,count(*) as expected from slt_private.import_stage group by entity loop
  execute format('select count(*) from public.%I where deleted_at is null','slt_'||row.entity) into actual;
  if actual<>row.expected then raise exception 'Contagem divergente em %',row.entity; end if;
 end loop;
 select jsonb_object_agg(entity,total) into counts from(select entity,count(*) total from slt_private.import_stage group by entity) q;
 insert into slt_private.migration_runs(source_checksum,source_revision,records,counts) values(expected_checksum,source.revision,inserted,counts);
 update slt_private.release_state set active=true,source_checksum=expected_checksum,source_revision=source.revision,activated_at=now() where id=1;
 revoke all on public.slt360_state from authenticated;
 revoke all on function public.slt360_save(bigint,jsonb) from authenticated;
 return jsonb_build_object('records',inserted,'counts',counts,'source_revision',source.revision);
end $$;
create function slt_private.freeze_legacy_state() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if (select active from slt_private.release_state where id=1) then raise exception 'A base foi migrada. Recarregue o sistema para continuar.' using errcode='55000'; end if;
 return new;
end $$;
create trigger freeze_legacy_after_migration before update or delete on public.slt360_state for each row execute function slt_private.freeze_legacy_state();
revoke all on all functions in schema slt_private from public,anon,authenticated;
revoke all on all tables in schema slt_private from public,anon,authenticated;
commit;
